#webcamPanel .webcam-frame { width:100%; aspect-ratio:16 / 9; background:#102535; border-radius:7px; overflow:hidden; }
#webcamPanel iframe, #webcamPanel .webcam-frame img { display:block; width:100%; height:100%; border:0; object-fit:contain; }
#webcamPanel .webcam-external { box-sizing:border-box; display:flex; flex-direction:column; align-items:center; justify-content:center; height:100%; padding:16px; text-align:center; }
#webcamPanel .webcam-external a { display:inline-block; padding:10px 14px; border:1px solid #5da3ff; border-radius:7px; background:#203f60; color:#fff; font-weight:600; }
#webcamPanel #webcamStatus { margin:8px 0 0; color:#b8cbe1; font-size:12px; }
#webcamPanel .webcam-source { display:flex; align-items:center; flex-wrap:wrap; gap:8px; margin-top:8px; color:#b8cbe1; font-size:11px; }
#webcamPanel .webcam-source > span { flex:1 1 auto; }
#webcamPanel a { color:#93c6ff; text-decoration:underline; }
#webcamPanel #webcamRetry { width:32px; height:32px; min-width:32px; min-height:32px !important; padding:0 !important; font-size:20px !important; line-height:1; }
#webcamPanel[data-player-state="unavailable"] #webcamStatus { color:#ffcb85; }
@media (max-width:900px), (max-width:1366px) and (any-pointer:coarse), (max-height:560px) and (pointer:coarse) {
  #webcamPanel { top:85px; width:min(360px,calc(100% - 16px)); max-height:calc(100dvh - 205px); padding:10px; }
  #webcamPanel #webcamClose { width:44px; height:44px; min-height:44px !important; flex-basis:44px; }
  #webcamPanel #webcamRetry { width:44px; height:44px; min-height:44px !important; min-width:44px; }
  #webcamPanel .webcam-source > a { display:flex; align-items:center; min-height:44px; }
  #webcamChoice { min-height:44px !important; }
  #webcamPanel .webcam-frame { max-height:34dvh; }
}
body.exporting .webcam-map-marker, body.exporting #webcamPanel, .export-stage .webcam-map-marker, .export-stage #webcamPanel { display:none !important; }
@media print { html body .webcam-map-marker, #webcamPanel { display:none !important; } }


